const sql=require("mssql"),mysql=require("mysql2/promise"),{getSourceConfig:getSourceConfig,getTargetConfig:getTargetConfig}=require("./db.helper"),dbConfig=getTargetConfig(),mssqlConfig1=getSourceConfig(),mssqlConfig2=getSourceConfig({port:433});async function migrateICD(){let e;try{try{e=await sql.connect(mssqlConfig1)}catch(t){e=await sql.connect(mssqlConfig2)}const t=await mysql.createConnection(dbConfig),n=(await e.request().query("\n            SELECT DISTINCT\n                ICD_KODU as code,\n                ACIKLAMA as name\n            FROM LST_ICDKODLARI\n            WHERE ICD_KODU IS NOT NULL AND LEN(ICD_KODU) > 0\n        ")).recordset;await t.execute("SET FOREIGN_KEY_CHECKS = 0"),await t.execute("TRUNCATE TABLE sys_icd10"),await t.execute("SET FOREIGN_KEY_CHECKS = 1");let a=0,s=0;const i=1e3;for(let e=0;e<n.length;e+=i){const o=n.slice(e,e+i).map((e=>[e.code.trim(),e.name?e.name.trim():"Tanımsız"]));try{await t.query("INSERT IGNORE INTO sys_icd10 (code, name) VALUES ?",[o]),a+=o.length,process.stdout.write(`\rProgress: ${a}/${n.length}`)}catch(e){s++}}await t.end(),await e.close()}catch(e){}}migrateICD();